declare(strict_types=1);

namespace paygw_payway\external;

use coding_exception;
use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_value;
use core_external\external_single_structure;
use core_payment\helper as payment_helper;
use invalid_parameter_exception;
use moodle_exception;
use core\lock\lock_config;
use paygw_payway\local\api_configuration;
use paygw_payway\local\api_response;
use paygw_payway\local\payment;
use paygw_payway\local\payway_api;
use paygw_payway\local\payment_processing_error_email;
use paygw_payway\local\unexpected_status_email;

/**
 * This class contains a list of webservice functions related to the PayWay payment gateway.
 *
 * @package    paygw_payway
 * @copyright  2026 Catalyst IT Australia
 * @author     Matthew Hilton <matthewhilton@catalyst-au.net>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class process_payment extends external_api {
    /**
     * Returns description of method parameters.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'component' => new external_value(PARAM_COMPONENT, 'Component'),
            'paymentarea' => new external_value(PARAM_AREA, 'Payment area in the component'),
            'itemid' => new external_value(PARAM_INT, 'An identifier for payment area in the component'),
            'token' => new external_value(PARAM_ALPHANUMEXT, 'The single-use token generated by payway.js'),
            'idempotencykey' => new external_value(PARAM_ALPHANUMEXT, 'The PayWay idempotency key'),
        ]);
    }

    /**
     * Processes the given single-use token and completes the payment.
     *
     * @param string $component
     * @param string $paymentarea
     * @param int $itemid
     * @param string $token
     * @param string $idempotencykey unique key used to avoid duplicate payment requests
     * @return string[]
     */
    public static function execute(
        string $component,
        string $paymentarea,
        int $itemid,
        string $token,
        string $idempotencykey
    ): array {
        global $PAGE, $USER;
        self::validate_parameters(self::execute_parameters(), [
            'component' => $component,
            'paymentarea' => $paymentarea,
            'itemid' => $itemid,
            'token' => $token,
            'idempotencykey' => $idempotencykey,
        ]);
        $PAGE->set_context(\context_system::instance());

        if (isguestuser()) {
            throw new moodle_exception('guestsarenotallowed', 'error');
        }

        // Both PayWay single-use tokens and client-generated idempotency keys use the canonical UUID format.
        // Reject malformed values before sending the token in a request body or the key in an HTTP header.
        $uuidpattern = '/\A[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\z/i';
        if (!preg_match($uuidpattern, $token) || !preg_match($uuidpattern, $idempotencykey)) {
            throw new invalid_parameter_exception('Invalid PayWay token or idempotency key.');
        }

        if (defined('BEHAT_SITE_RUNNING') && get_config('paygw_payway', 'behat_force_payment_error')) {
            throw new moodle_exception('error:paymentsetupfailed', 'paygw_payway');
        }

        // Lookup the payment gateway to get credentials.
        $config = payment_helper::get_gateway_configuration($component, $paymentarea, $itemid, 'payway');
        $payable = payment_helper::get_payable($component, $paymentarea, $itemid);
        $credentials = api_configuration::from_stored_config((object) $config);
        $api = payway_api::new($credentials);
        $notifyprocessingerror = function (string $intro, array $details)
 use ($credentials, $USER, $component, $paymentarea, $itemid): void {

            if (empty($credentials->notificationemail)) {
                return;
            }
            payment_processing_error_email::send(
                $credentials->notificationemail,
                $intro,
                $USER,
                $component,
                $paymentarea,
                $itemid,
                $details,
            );
        };

        // While out idempotency token will stop multiple payment attempts within a single session,
        // it will not reject multiple payment requests for a single user across multiple sessions.
        // We only hold the lock for the duration of the request, however, we check for potential
        // duplicate orders at deliver_order stage, and if found will notify in that super rare edge case.
        $lockfactory = lock_config::get_lock_factory('paygw_payway');
        $lock = $lockfactory->get_lock("paygw_payway:{$component}:{$paymentarea}:{$itemid}:{$USER->id}", 0);
        if (!$lock) {
            throw new moodle_exception('paymentalreadyprocessing', 'paygw_payway');
        }

        try {
            if (defined('BEHAT_SITE_RUNNING') && !get_config('paygw_payway', 'behat_use_real_payment_api')) {
                $res = self::get_behat_mock_payment_response($token, $idempotencykey);
            } else {
                $res = $api->process_payment(
                    singleusetoken: $token,
                    idempotencykey: $idempotencykey,
                    price: (float) $payable->get_amount(),
                    // This can be anything, it's for our reference only.
                    customernumber: (int) $USER->id,
                );
            }
            // Not succesful here means network or other connection error,
            // NOT a failed payment (e.g. declined card).
            if (!$res->is_success()) {
                // PayWay distinguishes user-correctable 422 responses from
                // retryable 429/503 and transport failures.
                // See https://www.payway.com.au/docs/rest.html#reference-http-response-codes (PayWay).
                debugging(
                    'PayWay payment request failed: ' . json_encode([
                        'httpcode' => $res->httpcode,
                        'curlerrno' => $res->curlerrno,
                        'body' => $res->body,
                        'component' => $component,
                        'paymentarea' => $paymentarea,
                        'itemid' => $itemid,
                        'userid' => $USER->id,
                        'idempotencykey' => $idempotencykey,
                    ]),
                    DEBUG_NORMAL,
                );

                if ($res->curlerrno !== 0) {
                    $notifyprocessingerror(
                        get_string('email:networkerror:intro', 'paygw_payway'),
                        [
                            'HTTP status' => $res->httpcode,
                            'cURL error' => $res->curlerrno,
                            'Idempotency key' => $idempotencykey,
                        ],
                    );
                }

                if ($res->is_retryable()) {
                    $retryafter = defined('BEHAT_SITE_RUNNING')
                        ? (int) get_config('paygw_payway', 'behat_retry_after_seconds')
                        : 20;
                    return [
                        'status' => 'retry',
                        'retryafter' => $retryafter > 0 ? $retryafter : 20,
                        'message' => get_string('paymentretrying', 'paygw_payway'),
                    ];
                }

                return [
                    'status' => 'error',
                    'message' => $res->httpcode === 422
                        ? get_string('paymentdetailsinvalid', 'paygw_payway')
                        : get_string('paymentfailed', 'paygw_payway'),
                ];
            }

            // A successful HTTP response does not necessarily mean approved;
            // PayWay requires checking the transaction status.
            // See https://www.payway.com.au/docs/rest.html#transactions-model .
            $paymentresult = payment::try_parse($res->body);
            if ($paymentresult->is_err()) {
                debugging('Unexpected PayWay payment response: ' . $res->body, DEBUG_NORMAL);
                $notifyprocessingerror(
                    get_string('email:responseerror:intro', 'paygw_payway'),
                    [
                        'HTTP status' => $res->httpcode,
                        'Error' => $paymentresult->error,
                        'Idempotency key' => $idempotencykey,
                    ],
                );
                throw new coding_exception($paymentresult->error);
            }
            $payment = $paymentresult->unwrap();

            if ($payment->is_accepted()) {
                try {
                    $paymentid = payment_helper::save_payment(
                        accountid: $payable->get_account_id(),
                        component: $component,
                        paymentarea: $paymentarea,
                        itemid: $itemid,
                        userid: (int) $USER->id,
                        amount: (float) $payable->get_amount(),
                        currency: $payable->get_currency(),
                        gateway: 'payway',
                    );
                    if (
                        !payment_helper::deliver_order(
                            component: $component,
                            paymentarea: $paymentarea,
                            itemid: $itemid,
                            paymentid: $paymentid,
                            userid: (int) $USER->id
                        )
                    ) {
                        throw new coding_exception('Payment delivery failed.');
                    }
                } catch (\Throwable $e) {
                    $notifyprocessingerror(
                        get_string('email:responseerror:intro', 'paygw_payway'),
                        [
                            'HTTP status' => $res->httpcode,
                            'Transaction ID' => $payment->transactionid,
                            'Receipt number' => $payment->receiptnumber,
                            'Error' => $e->getMessage(),
                            'Idempotency key' => $idempotencykey,
                        ],
                    );
                    throw $e;
                }
            }

            // Check if this is an unusual status that we should alert to.
            if ($payment->is_notifiable() && !empty($credentials->notificationemail)) {
                unexpected_status_email::send(
                    $credentials->notificationemail,
                    $payment,
                    $USER,
                    $component,
                    $paymentarea,
                    $itemid,
                );
            }

            return $payment->is_accepted() ? ['status' => 'ok'] : [
                'status' => 'error',
                'message' => get_string('failedpayment', 'paygw_payway'),
            ];
        } finally {
            $lock->release();
        }
    }

    /**
     * Return the next configured mock response for Behat, if one is configured.
     *
     * @param string $token PayWay single-use token
     * @param string $idempotencykey PayWay idempotency key
     * @return api_response
     */
    private static function get_behat_mock_payment_response(string $token, string $idempotencykey): api_response {
        // Some Behat payment flows may not configure an explicit response sequence.
        // Default them to an approved response instead of passing false to json_decode().
        $mocksequence = get_config('paygw_payway', 'behat_mock_payment_response_sequence') ?: '["approved"]';
        $sequence = json_decode($mocksequence, true, flags: JSON_THROW_ON_ERROR);
        $mockstatus = array_shift($sequence);
        set_config('behat_mock_payment_response_sequence', json_encode($sequence), 'paygw_payway');
        $attempts = json_decode(get_config('paygw_payway', 'behat_payment_attempts') ?: '[]', true);
        $attempts[] = ['token' => $token, 'idempotencykey' => $idempotencykey];
        set_config('behat_payment_attempts', json_encode($attempts), 'paygw_payway');

        $paymentbody = json_encode([
            'transactionId' => 123,
            'receiptNumber' => 456,
            'status' => in_array($mockstatus, ['approved', 'approved*', 'pending', 'declined', 'voided', 'suspended'])
                ? $mockstatus : 'declined',
            'responseCode' => '08',
            'responseText' => 'Mock PayWay response',
        ], JSON_THROW_ON_ERROR);
        $mockhttpcode = match ($mockstatus) {
            'retry' => 503,
            'invalid' => 422,
            'servererror' => 500,
            'networkerror' => 0,
            'responseerror' => 201,
            default => 201,
        };

        return new api_response(
            $mockhttpcode,
            $mockstatus === 'responseerror' ? '{"unexpected":"response"}' :
                ($mockhttpcode === 201 ? $paymentbody : '{}'),
            $mockstatus === 'networkerror' ? 28 : 0,
        );
    }

    /**
     * Returns description of method result value.
     *
     * @return external_single_structure
     */
    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'status' => new external_value(PARAM_TEXT, 'Result status of the payment processing'),
            'message' => new external_value(PARAM_TEXT, 'Error message', VALUE_OPTIONAL),
            'retryafter' => new external_value(PARAM_INT, 'Seconds before retrying', VALUE_OPTIONAL),
        ]);
    }
}
